/**
 * Returns a set of random departments from the master list (optionally filtered by industry)
 */
export function getRandomDepartments(count: number = 6, industry?: string): DepartmentTemplate[] {
  let pool = ALL_DEPARTMENTS;
  if (industry && industry !== 'All') {
    const matched = pool.filter((d) => d.industry.toLowerCase().includes(industry.toLowerCase()));
    if (matched.length > 0) pool = matched;
  }
  
  const shuffled = [...pool].sort(() => 0.5 - Math.random());
  return shuffled.slice(0, count);
}

/**
 * Filter departments with search query, industry, and category
 */
export function filterDepartments(
  query: string,
  industry?: string,
  category?: string
): DepartmentTemplate[] {
  const cleanQ = query.trim().toLowerCase();
  
  return ALL_DEPARTMENTS.filter((dept) => {
    // Industry match
    if (industry && industry !== 'All') {
      const matchIndustry = dept.industry.toLowerCase().includes(industry.toLowerCase());
      if (!matchIndustry) return false;
    }
    
    // Category match
    if (category && category !== 'All') {
      if (dept.category !== category) return false;
    }
    
    // Query text match
    if (cleanQ) {
      const inName = dept.name.toLowerCase().includes(cleanQ);
      const inLead = dept.leadTitle.toLowerCase().includes(cleanQ);
      const inDesc = dept.description.toLowerCase().includes(cleanQ);
      const inInd = dept.industry.toLowerCase().includes(cleanQ);
      return inName || inLead || inDesc || inInd;
    }
    
    return true;
  });
}
